import{_ as t,o as a,c as i,ag as s}from"./chunks/framework.D9kpkP22.js";const k=JSON.parse('{"title":"WebLink Addon","description":"","frontmatter":{},"headers":[],"relativePath":"weblink/index.md","filePath":"weblink/index.md"}'),o={name:"weblink/index.md"};function n(l,e,r,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="weblink-addon" tabindex="-1">WebLink Addon <a class="header-anchor" href="#weblink-addon" aria-label="Permalink to &quot;WebLink Addon&quot;">​</a></h1><p><strong>WebLink</strong> is a powerful IcedSpear addon that bridges your Minecraft server with your website. It enables secure account linking, real-time data fetching, and remote command execution.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Secure Account Linking</strong>: Players link their Minecraft account to a website account using a temporary 6-digit code.</li><li><strong>Webhook API</strong>: A built-in HTTP server exposes endpoints for your website to query player data.</li><li><strong>Remote Control</strong>: Execute console commands via secure webhooks.</li><li><strong>SQLite Storage</strong>: Fast, local storage for link data (no MySQL required).</li></ul><hr><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li><strong>Download</strong>: Get the <code>WebLink.jar</code> from the official release channel.</li><li><strong>Install</strong>: Place the jar in your server&#39;s <code>plugins/</code> folder.</li><li><strong>Dependencies</strong>: Ensure <strong>IcedSpear</strong> is installed and running.</li><li><strong>Restart</strong>: Restart the server to generate the configuration files.</li><li><strong>Configure</strong>: Edit <code>plugins/WebLink/config.yml</code> to set the <code>webhook-port</code> and <code>cors-origin</code>.</li></ol><hr><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><h3 id="player-commands" tabindex="-1">Player Commands <a class="header-anchor" href="#player-commands" aria-label="Permalink to &quot;Player Commands&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Permission</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/weblink link</code></td><td style="text-align:left;">None</td><td style="text-align:left;">Generates a 6-digit code to link your account.</td></tr><tr><td style="text-align:left;"><code>/weblink unlink</code></td><td style="text-align:left;">None</td><td style="text-align:left;">Unlinks your current account.</td></tr><tr><td style="text-align:left;"><code>/weblink status</code></td><td style="text-align:left;">None</td><td style="text-align:left;">Checks if your account is currently linked.</td></tr></tbody></table><hr><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The <code>config.yml</code> for WebLink is simple:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Port for the internal HTTP server</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">webhook-port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25531</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CORS Origin for web requests (use &quot;*&quot; for dev, your domain for prod)</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cors-origin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://yourwebsite.com&quot;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Secret key for signing/verifying webhook requests (keep this safe!)</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">webhook-secret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;change-this-to-a-secure-random-string&quot;</span></span></code></pre></div><hr><h2 id="webhook-api" tabindex="-1">Webhook API <a class="header-anchor" href="#webhook-api" aria-label="Permalink to &quot;Webhook API&quot;">​</a></h2><p>WebLink runs a local HTTP server (default port <code>25531</code>) that accepts JSON requests.</p><h3 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h3><p>(Implementation dependent - typically requires a shared secret or token signature).</p><h3 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h3><h4 id="post-webhook-check-link" tabindex="-1"><code>POST /webhook/check-link</code> <a class="header-anchor" href="#post-webhook-check-link" aria-label="Permalink to &quot;`POST /webhook/check-link`&quot;">​</a></h4><p>Checks if a website account ID is linked to any Minecraft players.</p><ul><li><strong>Input</strong>: <code>{&quot;accid&quot;: &quot;hashed_account_id&quot;}</code></li><li><strong>Output</strong>:<div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;linked&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;accounts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;uuid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;username&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PlayerName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;online&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li></ul><h4 id="post-webhook-verify-code" tabindex="-1"><code>POST /webhook/verify-code</code> <a class="header-anchor" href="#post-webhook-verify-code" aria-label="Permalink to &quot;`POST /webhook/verify-code`&quot;">​</a></h4><p>Verifies a 6-digit link code entered by a user on the website.</p><ul><li><strong>Input</strong>: <code>{&quot;code&quot;: &quot;123456&quot;, &quot;accid&quot;: &quot;hashed_account_id&quot;}</code></li><li><strong>Output</strong>: <code>{&quot;success&quot;: true, &quot;uuid&quot;: &quot;...&quot;, &quot;username&quot;: &quot;...&quot;}</code></li></ul><h4 id="post-webhook-execute-command" tabindex="-1"><code>POST /webhook/execute-command</code> <a class="header-anchor" href="#post-webhook-execute-command" aria-label="Permalink to &quot;`POST /webhook/execute-command`&quot;">​</a></h4><p>Executes a console command.</p><ul><li><strong>Input</strong>: <code>{&quot;command&quot;: &quot;say Hello World&quot;}</code></li><li><strong>Output</strong>: <code>{&quot;success&quot;: true, &quot;output&quot;: &quot;...&quot;}</code></li></ul><h4 id="post-webhook-check-online" tabindex="-1"><code>POST /webhook/check-online</code> <a class="header-anchor" href="#post-webhook-check-online" aria-label="Permalink to &quot;`POST /webhook/check-online`&quot;">​</a></h4><p>Checks if a specific player is online.</p><ul><li><strong>Input</strong>: <code>{&quot;uuid&quot;: &quot;...&quot;}</code></li><li><strong>Output</strong>: <code>{&quot;online&quot;: true}</code></li></ul><h4 id="get-webhook-get-friends-uuid" tabindex="-1"><code>GET /webhook/get-friends?uuid=...</code> <a class="header-anchor" href="#get-webhook-get-friends-uuid" aria-label="Permalink to &quot;`GET /webhook/get-friends?uuid=...`&quot;">​</a></h4><p>Returns the friend list of a player (via IcedSpear API).</p><h4 id="get-webhook-get-party-uuid" tabindex="-1"><code>GET /webhook/get-party?uuid=...</code> <a class="header-anchor" href="#get-webhook-get-party-uuid" aria-label="Permalink to &quot;`GET /webhook/get-party?uuid=...`&quot;">​</a></h4><p>Returns the current party information of a player.</p><h4 id="get-webhook-get-map-uuid" tabindex="-1"><code>GET /webhook/get-map?uuid=...</code> <a class="header-anchor" href="#get-webhook-get-map-uuid" aria-label="Permalink to &quot;`GET /webhook/get-map?uuid=...`&quot;">​</a></h4><p>Returns the current map instance a player is in.</p><h4 id="get-webhook-get-available-maps" tabindex="-1"><code>GET /webhook/get-available-maps</code> <a class="header-anchor" href="#get-webhook-get-available-maps" aria-label="Permalink to &quot;`GET /webhook/get-available-maps`&quot;">​</a></h4><p>Returns a list of all available maps defined in IcedSpear.</p><hr><h2 id="database-schema" tabindex="-1">Database Schema <a class="header-anchor" href="#database-schema" aria-label="Permalink to &quot;Database Schema&quot;">​</a></h2><p>WebLink uses a local SQLite database (<code>linked_accounts.db</code>) located in the plugin folder.</p><h3 id="table-linked-accounts" tabindex="-1">Table: <code>linked_accounts</code> <a class="header-anchor" href="#table-linked-accounts" aria-label="Permalink to &quot;Table: `linked_accounts`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Column</th><th style="text-align:left;">Type</th><th style="text-align:left;">Constraints</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>uuid</code></td><td style="text-align:left;"><code>TEXT</code></td><td style="text-align:left;"><code>UNIQUE NOT NULL</code></td><td style="text-align:left;">Minecraft Player UUID.</td></tr><tr><td style="text-align:left;"><code>accid</code></td><td style="text-align:left;"><code>TEXT</code></td><td style="text-align:left;"><code>NOT NULL</code></td><td style="text-align:left;">Hashed Website Account ID.</td></tr></tbody></table><ul><li><strong>Relationship</strong>: One-to-Many (One website account can be linked to multiple Minecraft accounts, but one Minecraft account can only be linked to one website account).</li></ul>',47)])])}const p=t(o,[["render",n]]);export{k as __pageData,p as default};
